def minIncrements(nums):
    size = max(nums) + len(nums) + 1
    cnt = [0] * size
    for x in nums:
        cnt[x] += 1
    pending = 0
    moves = 0
    for v in range(size):
        pending += cnt[v]
        if pending:
            pending -= 1
            moves += pending
    return moves
